deps = list(zip(values('Dependencies', 'K38:K43'), values('Dependencies', 'L38:L43')))
succs = {}
preds = {}
for s, p in deps:
    succs.setdefault(p, []).append(s)
    preds.setdefault(s, []).append(p)

# Calculate earliest start/finish
es = {t: 0 for t in tasks}
ef = {t: tasks[t] for t in tasks}
changed = True
while changed:
    changed = False
    for t in tasks:
        p_list = preds.get(t, [])
        if p_list:
            max_p = max(ef[p] for p in p_list)
            if max_p > es[t]:
                es[t] = max_p
                new_ef = es[t] + tasks[t]
                if new_ef > ef[t]:
                    ef[t] = new_ef
                    changed = True

project_duration = max(ef[t] for t in tasks)

# Calculate latest start/finish
ls = {t: project_duration - tasks[t] for t in tasks}
lf = {t: project_duration for t in tasks}
changed = True
while changed:
    changed = False
    for t in tasks:
        s_list = succs.get(t, [])
        if s_list:
            min_s = min(ls[s] for s in s_list)
            if min_s < lf[t]:
                lf[t] = min_s
                new_ls = lf[t] - tasks[t]
                if new_ls < ls[t]:
                    ls[t] = new_ls
                    changed = True

result = int(ls['Permit'] - es['Permit'])

